@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class Institution {
  + institutionCode : string
}

class ScientificArticle {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
}

class TechnicalReport extends ScientificArticle {
}

class AuthorPosition {
  + position : string
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "0..*" Institution : works for
Person "1" -- "0..*" ScientificArticle : author
Person "0..*" -- "0..*" ScientificArticle : reviewer
ScientificArticle "1" -- "1..*" AuthorPosition
Person "1" -- "1..*" AuthorPosition : occupies

Institution "1" -- "0..*" TechnicalReport : publishes
Publisher "1" -- "0..*" Journal : publishes
Institution "0..*" -- "0..*" Journal : subscribes
Journal "1" -- "0..*" PeerReviewedPaper : publishes

@enduml

